package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;
/** Production WebView and SQLite; replay of a real provider plan, then fault injection. */
public final class LayoutFlowTest extends DocumentEditorTest {
 String fixture(String name)throws Exception{try(InputStream in=getContext().getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
 void formatPreview()throws Exception{click("#doc-format");until("!!document.querySelector('#doc-preview')");}
 void rhythm(String root,String block)throws Exception{
  String box="document.querySelector('"+root+"')";
  check(h.js("(()=>{const b="+box+",p=[...b.querySelectorAll('"+block+">p')];return p.length===7&&p.every(p=>getComputedStyle(p).fontSize==='17px'&&getComputedStyle(p).lineHeight==='29px'&&getComputedStyle(p).marginTop===(p.previousElementSibling?.tagName==='H3'?'8px':'0px')&&getComputedStyle(p).marginBottom==='0px')&&[...b.querySelectorAll('strong')].every(s=>getComputedStyle(s).fontSize==='17px'&&getComputedStyle(s).lineHeight==='29px')})()").equals("true"),"Body and bold share 17px text / 29px line pitch without chat margins: "+root);
  check(h.js("(()=>{const blocks=[..."+box+".querySelectorAll(':scope>"+block+"')];return blocks.every((b,i)=>{const prev=blocks[i-1],gap=prev?(prev.classList.contains('doc-heading')&&!prev.classList.contains('doc-heading-body')?8:b.classList.contains('doc-heading')?20:12):0;return Math.abs(parseFloat(getComputedStyle(b).marginTop)-gap)<.1})})()").equals("true"),"Paragraph / section / heading gaps have one owner and no doubled spacing: "+root);
  check(h.js("(()=>{const b="+box+",origin=b.getBoundingClientRect().left,stride=b.id==='doc-flow'?document.querySelector('#doc-viewport').clientWidth+36:Infinity;let checked=0;return [...b.querySelectorAll('"+block+">p')].every(p=>{const range=document.createRange();range.selectNodeContents(p);const columns={};for(const r of range.getClientRects()){const col=Math.floor((r.left-origin+.5)/stride),key=Math.round(r.top*2)/2;(columns[col]||(columns[col]=new Set())).add(key)}return Object.values(columns).every(rows=>{const ys=[...rows].sort((a,b)=>a-b);for(let i=1;i<ys.length;i++){checked++;if(Math.abs(ys[i]-ys[i-1]-29)>1)return false}return true})})&&checked>=4})()").equals("true"),"Measured paragraph line spacing stays uniform even across bold text: "+root);
 }
 @Override public void onStart(){Bundle result=new Bundle();try{
  h=new MainHost(this);h.open();model();String source=fixture("layout-history.txt"),title="蒲氏家族三次满门抄斩",plan=fixture("layout-history-plan.json");
  h.js("window.__historyPlan="+plan+";window.__layoutSource="+JSONObject.quote(source)+";window.__layoutTitle="+JSONObject.quote(title)+";window.__layoutFail='';window.__layoutDelay=20;window.__layoutOriginal=LifeNative;LifeNative={call:(a,p,id)=>{if(a!=='ask'||JSON.parse(p).tool.name!=='plan_record_layout'){__layoutOriginal.call(a,p,id);return;}const request=JSON.parse(p);__calls.push(request);const us=JSON.parse(request.messages.at(-1).content).units;let out=JSON.parse(JSON.stringify(__historyPlan));if(__layoutFail==='omit')out.sections.pop();if(__layoutFail==='duplicate')out.sections[0].blocks[0].ids.push('u1');if(__layoutFail==='reorder')out.sections[0].blocks[0].ids.reverse();if(__layoutFail==='network'){setTimeout(()=>nativeReply({id,error:'合成网络断开'}),__layoutDelay);return;}if(__layoutFail==='auto')out={sections:[{heading:[],blocks:us.map(u=>({ids:[u.id],style:u.protected?'preserve':'paragraph',emphasis:[]}))}]};setTimeout(()=>nativeReply({id,data:{text:JSON.stringify(out),model:'replay-real-provider-plan'}}),__layoutDelay);}};");
  open("learning");input(title,source);int count=records().length();formatPreview();
  check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))===__layoutSource").equals("true"),"Real-plan preview leaves the original editor unchanged");
  check(records().length()==count,"Preview never writes to records database");
  check(h.js("document.querySelectorAll('#doc-flow h3').length===5&&document.querySelectorAll('#doc-flow strong').length===8&&document.querySelectorAll('#doc-flow p:not(.document-caption)').length===7").equals("true"),"User history sample renders five sections, seven paragraphs and eight limited highlights");
  check(h.js("[...document.querySelectorAll('#doc-flow .doc-source>p')].every(p=>!/[，,]$/.test(p.textContent.trim()))").equals("true"),"No prose paragraph is left hanging at a comma");
  check(h.js("document.querySelector('#doc-flow').innerText.includes('8岁都小皇帝')&&document.querySelector('#doc-flow').innerText.includes('3000')").equals("true"),"User wording and numbers remain intact, not silently fact-corrected");rhythm("#doc-flow",".doc-source");
  check(h.js("getComputedStyle(document.querySelector('#doc-flow>h1')).marginTop==='0px'&&getComputedStyle(document.querySelector('#doc-flow>h1')).marginBottom==='8px'").equals("true"),"Article title no longer inherits oversized browser margins");
  check(h.js("(()=>{const f=document.querySelector('#doc-flow'),origin=f.getBoundingClientRect().left,stride=document.querySelector('#doc-viewport').clientWidth+36;return [...f.querySelectorAll('.doc-heading')].every(h=>{const heading=h.querySelector('h3'),a=[...heading.getClientRects()].at(-1),b=(heading.nextElementSibling||h.nextElementSibling.firstElementChild).getClientRects()[0];return Math.floor((a.left-origin+.5)/stride)===Math.floor((b.left-origin+.5)/stride)})})()").equals("true"),"Section headings stay with following body instead of being orphaned at a page foot");
  h.screenshot("layout-history-preview.png");
  int pages=Integer.parseInt(h.js("Number(document.querySelector('#doc-page').textContent.split('/')[1].trim())"));
  for(int i=1;i<=pages;i++){check(h.js("(()=>{const v=document.querySelector('#doc-viewport').getBoundingClientRect(),w=document.createTreeWalker(document.querySelector('#doc-flow'),NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(!n.textContent.trim())continue;const r=document.createRange();r.selectNodeContents(n);if([...r.getClientRects()].some(x=>x.right>v.left&&x.left<v.right&&x.bottom>v.top&&x.top<v.bottom))return true}return false})()").equals("true"),"Reader page "+i+" contains visible text, not an empty pagination tail");h.screenshot("layout-history-page-"+i+".png");if(i<pages){click("#doc-next");Thread.sleep(220);}}
  check(h.js("(()=>{const r=document.querySelector('#doc-preview').getBoundingClientRect();return r.bottom<=innerHeight+1&&document.documentElement.scrollWidth<=innerWidth+1})()").equals("true"),"Preview actions fit phone width and height");
  click("#doc-cancel-format");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))===__layoutSource").equals("true"),"Cancel restores exact original");
  formatPreview();click("#doc-apply");h.js("window.__layoutFormatted=DocumentLayout.compile(__layoutSource,[__historyPlan],__layoutTitle)");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))===__layoutFormatted").equals("true"),"Adoption inserts locally assembled Markdown, not model prose");
  click("#doc-mode");
  rhythm("#doc-body",".rich-block");h.screenshot("layout-history-editor.png");
  click("#doc-undo");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))===__layoutSource").equals("true"),"Undo restores full original");click("#doc-redo");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))===__layoutFormatted").equals("true"),"Redo restores accepted layout");
  click("#doc-save");if(h.js("document.querySelector('#confirm-dialog').open").equals("true"))click("#confirm-ok");until("document.querySelector('#doc-mode').textContent==='编辑'&&!document.querySelector('#doc-save').disabled");check(records().length()==count+1,"Saving commits one structured note after explicit save");close();
  for(String mode:new String[]{"omit","duplicate","reorder","network"}){open("work_note");input(title,source);h.js("__layoutFail="+JSONObject.quote(mode));click("#doc-format");until("!document.querySelector('#doc-format').disabled");check(h.js("!document.querySelector('#doc-preview')&&DocumentRich.serialize(document.querySelector('#doc-body'))===__layoutSource").equals("true"),"Bad plan/network failure retains original: "+mode);close();}
  h.js("__layoutFail='';__layoutDelay=650");open("idea");input(title,source);click("#doc-format");input(title,source+"新增加的内容不能被覆盖。");Thread.sleep(1000);check(h.js("!document.querySelector('#doc-preview')&&document.querySelector('#doc-body').textContent.includes('新增加的内容不能被覆盖')").equals("true"),"Concurrent edit is not overwritten by late model response");close();
  h.js("__layoutFail='auto';__layoutDelay=10");open("experience");String longText="长文完整性检查。保留原文与条件，不能只排开头。\n";StringBuilder text=new StringBuilder();for(int i=0;i<400;i++)text.append(longText);input("长文测试",text.toString());h.js("window.__longLayoutBody=DocumentRich.serialize(document.querySelector('#doc-body'));window.__layoutCallsBefore=__calls.length");formatPreview();check(h.js("__calls.length-__layoutCallsBefore>=2").equals("true"),"Long note is completely batched beyond 6000 characters");click("#doc-apply");check(h.js("RecordDocument.plain(DocumentRich.serialize(document.querySelector('#doc-body'))).replace(/，/g,'。')===RecordDocument.plain(__longLayoutBody).replace(/，/g,'。')").equals("true"),"Long-note body retains every word and allows only paragraph-ending punctuation changes");close();
  result.putString("stream","PASS LayoutFlowTest: "+passed+" checks; provider-plan replay, no paid calls\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable ex){try{h.screenshot("layout-failure.png");}catch(Exception ignored){}result.putString("stream","FAIL LayoutFlowTest after "+passed+": "+ex+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
